    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int k;
    if (!(cin >> n >> k)) return 0;

    // Factorize n (n <= 1e15)
    vector<pair<long long,int>> factors;
    {
        long long x = n;
        for (long long p = 2; p * p <= x; ++p) {
            if (x % p == 0) {
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    ++cnt;
                }
                factors.push_back({p, cnt});
            }
        }
        if (x > 1) factors.push_back({x, 1});
    }

    long long ans = 1;
    for (auto &pr : factors) {
        long long p = pr.first;
        int e = pr.second;

        // dp[t][i]: probability that exponent becomes i after t steps
        vector<long long> dp(e + 1), ndp(e + 1);
        dp[e] = 1; // initially exponent is e

        for (int step = 0; step < k; ++step) {
            fill(ndp.begin(), ndp.end(), 0);
            for (int i = 0; i <= e; ++i) {
                if (!dp[i]) continue;
                long long prob = dp[i];
                long long inv = modinv(i + 1);
                for (int j = 0; j <= i; ++j) {
                    ndp[j] = (ndp[j] + prob * inv) % MOD;
